<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net9.0</TargetFramework>
  </PropertyGroup>
  <ItemGroup>
    <PackageReference Include="MSBuild.StructuredLogger" Version="2.2.405" />
  </ItemGroup>
</Project>
EOF
cat > Program.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Collections.Generic;
using System.Linq;

var build = BinaryLog.ReadBuild("build.binlog");
var errors = new List<(string project, string code, string message, string file, int line)>();
var warnings = new List<(string project, string code, string message, string file)>();

build.VisitAllChildren<Error>(e => {
    var proj = "";
    var parent = e.Parent;
    while (parent != null) {
        if (parent is Project p) { proj = p.Name; break; }
        parent = (parent as TreeNode)?.Parent as BaseNode;
    }
    errors.Add((proj, e.Code ?? "", e.Text ?? "", e.File ?? "", e.LineNumber));
});

build.VisitAllChildren<Warning>(w => {
    var proj = "";
    var parent = w.Parent;
    while (parent != null) {
        if (parent is Project p) { proj = p.Name; break; }
        parent = (parent as TreeNode)?.Parent as BaseNode;
    }
    warnings.Add((proj, w.Code ?? "", w.Text ?? "", w.File ?? ""));
});

Console.WriteLine($"=== BUILD ERRORS ({errors.Count}) ===");
foreach (var g in errors.GroupBy(e => e.project))
{
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var e in g)
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
}

if (warnings.Any(w => w.code.StartsWith("NU") || w.code.StartsWith("MSB")))
{
    Console.WriteLine($"\n=== RELEVANT WARNINGS ===");
    foreach (var w in warnings.Where(w => w.code.StartsWith("NU") || w.code.StartsWith("MSB")))
        Console.WriteLine($"  [{w.code}] {w.project}: {w.message}");
}

// Check for failed targets
Console.WriteLine("\n=== FAILED PROJECTS ===");
build.VisitAllChildren<Project>(p => {
    if (!p.Succeeded)
        Console.WriteLine($"  FAILED: {p.Name} (target: {p.TargetFramework})");
});
EOF
