using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild("build.binlog");

// Show all projects and their dependencies
Console.WriteLine("=== PROJECTS IN BUILD ===");
build.VisitAllChildren<Project>(p => {
    Console.WriteLine($"  {p.Name} (TFW: {p.TargetFramework})");
});

// Show source files embedded in binlog
Console.WriteLine("\n=== EMBEDDED FILES ===");
var archive = build.SourceFilesArchive;
if (archive != null) {
    foreach (var f in archive.Files)
        Console.WriteLine($"  {f.FullPath}");
}

// Show the failing source file content
Console.WriteLine("\n=== UserService.cs content ===");
if (archive != null) {
    var file = archive.Files.FirstOrDefault(f => f.FullPath.Contains("UserService"));
    if (file != null) Console.WriteLine(file.Text);
}

// Show project file
Console.WriteLine("\n=== Services.csproj content ===");
if (archive != null) {
    var file = archive.Files.FirstOrDefault(f => f.FullPath.Contains("Services.csproj"));
    if (file != null) Console.WriteLine(file.Text);
}
EOF
